import java.util.*;

public class Main {
    static int n;
    static int best = Integer.MAX_VALUE;
    static int[][] cost;
    static boolean[] used;

    static void dfs(int worker, int sum) {
        if (sum >= best) {
            return;
        }
        if (worker == n) {
            best = sum;
            return;
        }
        for (int job = 0; job < n; job++) {
            if (used[job]) {
                continue;
            }
            used[job] = true;
            dfs(worker + 1, sum + cost[worker][job]);
            used[job] = false;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        cost = new int[n][n];
        used = new boolean[n];
        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                cost[i][j] = sc.nextInt();
            }
        }
        dfs(0, 0);
        System.out.println(best);
    }
}
