import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int rows = sc.nextInt();
        int cols = sc.nextInt();
        char[][] grid = new char[rows][];
        int r = 0;
        int c = 0;
        int d = 3;
        for (int i = 0; i < rows; i++) {
            grid[i] = sc.next().toCharArray();
            for (int j = 0; j < cols; j++) {
                if (grid[i][j] == 'S') {
                    r = i;
                    c = j;
                    grid[i][j] = '.';
                }
            }
        }

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        String dirs = "UDLR";
        for (char command : sc.next().toCharArray()) {
            if (command == 'F') {
                int nr = r + dr[d];
                int nc = c + dc[d];
                while (nr >= 0 && nr < rows && nc >= 0 && nc < cols) {
                    if (grid[nr][nc] == '#') {
                        break;
                    }
                    if (grid[nr][nc] == '*') {
                        grid[nr][nc] = '.';
                        break;
                    }
                    nr += dr[d];
                    nc += dc[d];
                }
            } else {
                d = dirs.indexOf(command);
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 0 && nr < rows && nc >= 0 && nc < cols && grid[nr][nc] == '.') {
                    r = nr;
                    c = nc;
                }
            }
        }

        int bricks = 0;
        for (char[] row : grid) {
            for (char cell : row) {
                if (cell == '*') {
                    bricks++;
                }
            }
        }
        System.out.println(r + " " + c + " " + bricks);
    }
}
