import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        List<int[]> live = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            int x = sc.nextInt() * 2;
            int y = sc.nextInt() * 2;
            int d = sc.nextInt();
            int e = sc.nextInt();
            live.add(new int[] {x, y, d, e});
        }

        int[] dx = {0, 0, -1, 1};
        int[] dy = {1, -1, 0, 0};
        int total = 0;
        for (int step = 1; step <= 80 && !live.isEmpty(); step++) {
            Map<String, List<int[]>> groups = new HashMap<>();
            for (int[] p : live) {
                p[0] += dx[p[2]];
                p[1] += dy[p[2]];
                if (Math.abs(p[0]) > 40 || Math.abs(p[1]) > 40) {
                    continue;
                }
                groups.computeIfAbsent(p[0] + ":" + p[1], k -> new ArrayList<>()).add(p);
            }

            live = new ArrayList<>();
            for (List<int[]> group : groups.values()) {
                if (group.size() == 1) {
                    live.add(group.get(0));
                } else {
                    for (int[] p : group) {
                        total += p[3];
                    }
                }
            }
        }
        System.out.println(total);
    }
}
